   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="app"></div>
     <script>
       const requiredIndicator = '<span class="required-mark" aria-hidden="true">*</span>';

       function FormField({
         id,
         label,
         type,
         required = false,
         autocomplete = "",
         hint = "",
         placeholder = "",
       }) {
         const hintId = hint ? `${id}-hint` : "";
         const errorId = `${id}-error`;
         const describedBy = [hintId, errorId].filter(Boolean).join(" ");

         return `
           <div class="form-field">
             <label for="${id}">${label} ${required ? requiredIndicator : ""}</label>
             <input
               id="${id}"
               name="${id}"
               type="${type}"
               ${required ? "required" : ""}
               ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
               ${placeholder ? `placeholder="${placeholder}"` : ""}
               aria-describedby="${describedBy}"
             />
             ${hint ? `<p class="field-hint" id="${hintId}">${hint}</p>` : ""}
             <p class="field-error" id="${errorId}" hidden></p>
           </div>
         `;
       }

       function ContactForm() {
         return `
           <form id="support-form" novalidate>
             <p class="status-message" id="form-status" role="status"></p>
             ${FormField({
               id: "fullName",
               label: "Full name",
               type: "text",
               required: true,
               autocomplete: "name",
               placeholder: "Jordan Lee",
             })}
             ${FormField({
               id: "email",
               label: "Email address",
               type: "email",
               required: true,
               autocomplete: "email",
               placeholder: "jordan@example.com",
             })}
             ${FormField({
               id: "phone",
               label: "Phone number",
               type: "tel",
               autocomplete: "tel",
               hint: "Optional. Use digits only or include punctuation, for example (555) 123-4567.",
               placeholder: "(555) 123-4567",
             })}
             <button type="submit">Send support request</button>
           </form>
         `;
       }

       function SupportPage() {
         return `
           <main id="main-content" tabindex="-1">
             <div class="page-shell">
               <section class="support-card" aria-labelledby="support-heading">
                 <p class="eyebrow">Support</p>
                 <h1 id="support-heading">Contact our support team</h1>
                 <p class="intro">
                   Share your details and we will follow up with the right next step for your request.
                 </p>
                 <p class="required-note"><span class="required-mark" aria-hidden="true">*</span> Required fields</p>
                 ${ContactForm()}
               </section>
             </div>
           </main>
         `;
       }

       function renderApp() {
         document.getElementById("app").innerHTML = SupportPage();
       }

       function getValidationMessage(input) {
         if (input.validity.valueMissing) {
           return `Error: Enter your ${input.name === "fullName" ? "full name" : "email address"}.`;
         }

         if (input.validity.typeMismatch) {
           return "Error: Enter an email address in the format name@example.com.";
         }

         return "";
       }

       function clearFieldError(input) {
         const error = document.getElementById(`${input.id}-error`);
         input.removeAttribute("aria-invalid");
         error.hidden = true;
         error.textContent = "";
       }

       function showFieldError(input, message) {
         const error = document.getElementById(`${input.id}-error`);
         input.setAttribute("aria-invalid", "true");
         error.hidden = false;
         error.textContent = message;
       }

       function validateForm(form) {
         const fields = Array.from(form.querySelectorAll("input"));
         let firstInvalidField = null;

         fields.forEach((input) => {
           const message = getValidationMessage(input);

           if (message) {
             showFieldError(input, message);
             if (!firstInvalidField) {
               firstInvalidField = input;
             }
           } else {
             clearFieldError(input);
           }
         });

         return firstInvalidField;
       }

       function setupForm() {
         const form = document.getElementById("support-form");
         const status = document.getElementById("form-status");

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           status.textContent = "";

           const firstInvalidField = validateForm(form);

           if (firstInvalidField) {
             firstInvalidField.focus();
             return;
           }

           status.textContent = "Your support request is ready to send.";
           form.reset();
         });

         form.querySelectorAll("input").forEach((input) => {
           input.addEventListener("input", () => {
             if (input.hasAttribute("aria-invalid")) {
               const message = getValidationMessage(input);
               if (message) {
                 showFieldError(input, message);
               } else {
                 clearFieldError(input);
               }
             }
           });
         });
       }

       renderApp();
       setupForm();
     </script>
